--[[
    VeevHUD - Spanish (Spain) (esES) Localization

    AI-GENERATED translation (by Claude) -- NOT yet reviewed by a native speaker.

    >> Contributions welcome! << Spotted an awkward or wrong string? Edit its
    L["..."] = "..." value below and open a pull request (or an issue) at
    https://github.com/veev-code/VeevHUD  -- native speakers especially appreciated.
    Any key omitted here falls back to English automatically (see enUS.lua).
]]

local L = LibStub("AceLocale-3.0"):NewLocale("VeevHUD", "esES")
if not L then return end

L["Outline"] = "Contorno"
L["Shadow"] = "Sombra"
L["Both"] = "Ambos"
L["None"] = "Ninguno"
L["Inherit (Global)"] = "Heredar (global)"
L["Off"] = "Desactivado"
L["Primary Row"] = "Fila primaria"
L["Primary + Secondary Rows"] = "Filas primaria + secundaria"
L["Secondary + Utility Rows"] = "Filas secundaria + utilidad"
L["Utility Row"] = "Fila de utilidad"
L["All Rows"] = "Todas las filas"
L["Prediction"] = "Predicción"
L["Fill"] = "Relleno"
L["Bar"] = "Barra"
L["Spark"] = "Destello"
L["Current"] = "Actual"
L["%"] = "%"
L["Current (%)"] = "Actual (%)"
L["Current / Max"] = "Actual / Máx."
L["Current / Max (%)"] = "Actual / Máx. (%)"
L["Deficit"] = "Déficit"
L["Abbreviated (4.5k)"] = "Abreviado (4.5k)"
L["Full (4523)"] = "Completo (4523)"
L["Comma (4,523)"] = "Con coma (4,523)"
L["Default: "] = "Por defecto: "
L["Core rotation abilities used every fight — your most important cooldowns."] = "Habilidades de rotación básica que usas en cada combate; tus tiempos de reutilización más importantes."
L["Throughput cooldowns, maintenance buffs, and situational damage or healing abilities."] = "Tiempos de reutilización de rendimiento, beneficios de mantenimiento y habilidades situacionales de daño o sanación."
L["Crowd control, interrupts, defensives, and movement abilities."] = "Control de masas, interrupciones, defensivas y habilidades de movimiento."
L["Totems, trinkets, and other supplementary icons."] = "Tótems, abalorios y otros iconos complementarios."
L["Enabled"] = "Activado"
L["Enables or disables this row. When disabled, abilities assigned to this row are hidden and the row takes no space on the HUD."] = "Activa o desactiva esta fila. Si está desactivada, las habilidades asignadas a esta fila se ocultan y la fila no ocupa espacio en la interfaz."
L["Size"] = "Tamaño"
L["Icon Size"] = "Tamaño de icono"
L["The size of each ability icon in this row, in pixels. Each row can have different-sized icons — for example, larger icons for your main rotation and smaller ones for utility."] = "El tamaño de cada icono de habilidad en esta fila, en píxeles. Cada fila puede tener iconos de distinto tamaño; por ejemplo, iconos más grandes para tu rotación principal y más pequeños para utilidad."
L["Max Icons"] = "Máx. iconos"
L["The maximum number of ability icons that can appear in this row. If you assign more spells than this limit, the extra ones won't be shown."] = "El número máximo de iconos de habilidad que pueden aparecer en esta fila. Si asignas más hechizos que este límite, los sobrantes no se mostrarán."
L["Aspect Ratio"] = "Relación de aspecto"
L["Override the icon shape for this row. |cffffffffInherit|r uses the global setting from Appearance."] = "Anula la forma de los iconos de esta fila. |cffffffffHeredar|r usa el ajuste global de Apariencia."
L["Inherit"] = "Heredar"
L["Square (1:1)"] = "Cuadrado (1:1)"
L["Slightly Compact"] = "Ligeramente compacto"
L["Compact (4:3)"] = "Compacto (4:3)"
L["Very Compact"] = "Muy compacto"
L["Ultra Compact (2:1)"] = "Ultracompacto (2:1)"
L["Flow Layout"] = "Disposición fluida"
L["Wraps icons into multiple lines instead of displaying them all in a single long line. The Icons Per Row setting controls the maximum icons per line.\n\nTo avoid a sparse last row, icons are moved down from the previous row — for example, 8 icons at 6 per row becomes 5 and 3 instead of 6 and 2."] = "Distribuye los iconos en varias líneas en lugar de mostrarlos todos en una sola línea larga. El ajuste Iconos por fila controla el máximo de iconos por línea.\n\nPara evitar una última fila escasa, los iconos se bajan de la fila anterior; por ejemplo, 8 iconos a 6 por fila pasan a ser 5 y 3 en lugar de 6 y 2."
L["Icons Per Row"] = "Iconos por fila"
L["The maximum number of icons on each line before wrapping to the next. Rows fill from the top, so earlier rows are always full.\n\nTo avoid a sparse last row, icons are moved down from the previous row — for example, 14 icons at 6 per row becomes 6, 5, 3 instead of 6, 6, 2."] = "El número máximo de iconos en cada línea antes de pasar a la siguiente. Las filas se llenan desde arriba, así que las primeras filas siempre están llenas.\n\nPara evitar una última fila escasa, los iconos se bajan de la fila anterior; por ejemplo, 14 iconos a 6 por fila pasan a ser 6, 5, 3 en lugar de 6, 6, 2."
L["Reorder the vertical layout of the HUD and adjust spacing between elements."] = "Reordena la disposición vertical de la interfaz y ajusta el espaciado entre elementos."
L["Up"] = "Arriba"
L["Down"] = "Abajo"
L["Gap above %s"] = "Espacio sobre %s"
L["Pixels of space between %s and %s."] = "Píxeles de espacio entre %s y %s."
L["VeevHUD"] = "VeevHUD"
L["Version "] = "Versión "
L["General"] = "General"
L["Global settings that affect the entire HUD. Individual modules have their own tabs."] = "Ajustes globales que afectan a toda la interfaz. Los módulos individuales tienen sus propias pestañas."
L["Position and Scale"] = "Posición y escala"
L["Horizontal Offset"] = "Desplazamiento horizontal"
L["Moves the entire HUD left or right from the center of the screen. Negative values shift it left, positive values shift it right. The range adjusts to your screen resolution."] = "Mueve toda la interfaz a la izquierda o a la derecha desde el centro de la pantalla. Los valores negativos la desplazan a la izquierda, los positivos a la derecha. El rango se ajusta a la resolución de tu pantalla."
L["Vertical Offset"] = "Desplazamiento vertical"
L["Moves the entire HUD up or down on your screen. Negative values move it below center, positive values move it above. The range adjusts to your screen resolution."] = "Mueve toda la interfaz hacia arriba o hacia abajo en tu pantalla. Los valores negativos la mueven por debajo del centro, los positivos por encima. El rango se ajusta a la resolución de tu pantalla."
L["Scale"] = "Escala"
L["Makes everything in the HUD bigger or smaller. 100% is the normal size. Increase if you have trouble seeing the icons, decrease if they take up too much screen space."] = "Hace que todo en la interfaz sea más grande o más pequeño. 100% es el tamaño normal. Auméntalo si te cuesta ver los iconos, redúcelo si ocupan demasiado espacio en pantalla."
L["Appearance"] = "Apariencia"
L["Font"] = "Fuente"
L["The font used for all text in the HUD, including cooldown timers, stack counts, health/resource values, and proc durations.\n\nIf you have font-sharing addons installed (SharedMedia, etc.), their fonts will appear here automatically."] = "La fuente usada para todo el texto de la interfaz, incluidos los temporizadores de tiempo de reutilización, los contadores de acumulación, los valores de salud/recurso y las duraciones de procs.\n\nSi tienes instalados complementos de fuentes compartidas (SharedMedia, etc.), sus fuentes aparecerán aquí automáticamente."
L["Text Color"] = "Color del texto"
L["The color used for cooldown countdowns, duration timers, and stack counts across all HUD elements."] = "El color usado para las cuentas atrás de tiempo de reutilización, los temporizadores de duración y los contadores de acumulación en todos los elementos de la interfaz."
L["Text Outline"] = "Contorno del texto"
L["Controls how text is rendered across all HUD elements.\n\n|cffffffffOutline|r — Font outline only.\n|cffffffffShadow|r — Drop shadow only (cleaner at small sizes).\n|cffffffffBoth|r — Font outline + drop shadow (maximum readability).\n|cffffffffNone|r — No outline or shadow.\n\nIndividual elements can override this in their own settings."] = "Controla cómo se representa el texto en todos los elementos de la interfaz.\n\n|cffffffffContorno|r — Solo contorno de fuente.\n|cffffffffSombra|r — Solo sombra paralela (más limpio en tamaños pequeños).\n|cffffffffAmbos|r — Contorno de fuente + sombra paralela (máxima legibilidad).\n|cffffffffNinguno|r — Sin contorno ni sombra.\n\nLos elementos individuales pueden anular esto en sus propios ajustes."
L["Bar Texture"] = "Textura de barra"
L["The texture used for all status bars in the HUD, including health, resource, combo point, and energy ticker bars.\n\nIf you have texture-sharing addons installed (SharedMedia, etc.), their textures will appear here automatically."] = "La textura usada para todas las barras de estado de la interfaz, incluidas las barras de salud, recurso, puntos de combo y marcador de energía.\n\nSi tienes instalados complementos de texturas compartidas (SharedMedia, etc.), sus texturas aparecerán aquí automáticamente."
L["Bar Gradient"] = "Degradado de barra"
L["Adds a subtle dark-to-light gradient across all status bars (health, resource, combo points, and energy ticker), giving them more visual depth instead of a flat solid color."] = "Añade un sutil degradado de oscuro a claro en todas las barras de estado (salud, recurso, puntos de combo y marcador de energía), dándoles más profundidad visual en lugar de un color sólido plano."
L["Icon Zoom"] = "Zoom de icono"
L["Zooms into each icon's artwork, cropping the edges. Affects ability rows and Aura Tracker. Useful for removing the default border that some spell textures have. 0% shows the full icon, 16% is a subtle crop."] = "Amplía la imagen de cada icono, recortando los bordes. Afecta a las filas de habilidades y al Rastreador de auras. Útil para eliminar el borde por defecto que tienen algunas texturas de hechizos. 0% muestra el icono completo, 16% es un recorte sutil."
L["Sound"] = "Sonido"
L["Sound Channel"] = "Canal de sonido"
L["Audio channel for all VeevHUD sound alerts.\n\n|cffffffffMaster|r — Always plays regardless of volume sliders.\n|cffffffffSound Effects|r — Respects the Sound Effects volume slider.\n|cffffffffMusic|r — Respects the Music volume slider.\n|cffffffffAmbience|r — Respects the Ambience volume slider."] = "Canal de audio para todas las alertas de sonido de VeevHUD.\n\n|cffffffffMaestro|r — Suena siempre, sin importar los controles de volumen.\n|cffffffffEfectos de sonido|r — Respeta el control de volumen de Efectos de sonido.\n|cffffffffMúsica|r — Respeta el control de volumen de Música.\n|cffffffffAmbiente|r — Respeta el control de volumen de Ambiente."
L["Register Sound Kit ID"] = "Registrar ID de kit de sonido"
L["Enter a WoW Sound Kit ID (a number) to register it as an available sound. Once registered, it appears in all sound dropdowns.\n\nBrowse IDs at: wowhead.com/sounds\n\nExamples: 8959 (raid warning), 11466 (Illidan), 8174 (PvP flag).\n\nNote: the speaker preview button in dropdowns does not work for Kit IDs, but the sound plays correctly in-game."] = "Introduce un ID de kit de sonido de WoW (un número) para registrarlo como sonido disponible. Una vez registrado, aparece en todos los menús de sonido.\n\nConsulta los ID en: wowhead.com/sounds\n\nEjemplos: 8959 (aviso de banda), 11466 (Illidan), 8174 (bandera JcJ).\n\nNota: el botón de previsualización de altavoz en los menús no funciona para los ID de kit, pero el sonido se reproduce correctamente en el juego."
L["Invalid Sound Kit ID: %s"] = "ID de kit de sonido no válido: %s"
L["Playing Kit ID %s — registered as %s (top of sound dropdowns)."] = "Reproduciendo ID de kit %s; registrado como %s (al principio de los menús de sonido)."
L["Sound Kit ID registration failed — LibSharedMedia not available."] = "Fallo al registrar el ID de kit de sonido; LibSharedMedia no disponible."
L["Visibility"] = "Visibilidad"
L["Out of Combat Opacity"] = "Opacidad fuera de combate"
L["Controls the HUD's visibility when not in combat. Use this to fade the HUD when out of combat so it's less distracting. 100% = fully visible, 50% = half transparent, 0% = invisible.\n\nNote: This setting is ignored while the config panel is open so you can see the HUD while configuring."] = "Controla la visibilidad de la interfaz cuando no estás en combate. Úsalo para atenuar la interfaz fuera de combate y que distraiga menos. 100% = totalmente visible, 50% = medio transparente, 0% = invisible.\n\nNota: este ajuste se ignora mientras el panel de configuración está abierto, para que puedas ver la interfaz mientras la configuras."
L["Hide on Flight Path"] = "Ocultar en ruta de vuelo"
L["Automatically hides the HUD when you're on a flight path (taxi). The HUD will reappear when you land. Useful to keep your screen clean while traveling.\n\nNote: This setting is ignored while the config panel is open so you can see the HUD while configuring."] = "Oculta automáticamente la interfaz cuando estás en una ruta de vuelo (taxi). La interfaz reaparecerá al aterrizar. Útil para mantener la pantalla despejada mientras viajas.\n\nNota: este ajuste se ignora mientras el panel de configuración está abierto, para que puedas ver la interfaz mientras la configuras."
L["Animations"] = "Animaciones"
L["Smooth Bar Animation"] = "Animación de barra suave"
L["Health bars, resource bars, and the resource-cost overlay on ability icons animate smoothly instead of jumping when values change."] = "Las barras de salud, las barras de recurso y la superposición de coste de recurso en los iconos de habilidad se animan con suavidad en lugar de saltar cuando cambian los valores."
L["Smooth Dim Transition"] = "Transición de atenuación suave"
L["When icons fade in or out (e.g., dimming on cooldown), the transition is gradual instead of instant. Disable for snappier visual feedback."] = "Cuando los iconos aparecen o desaparecen (p. ej., al atenuarse en tiempo de reutilización), la transición es gradual en lugar de instantánea. Desactívalo para una respuesta visual más rápida."
L["Ability Rows"] = "Filas de habilidades"
L["Default visual settings for all ability rows. Individual rows can override icon shape in their own tabs."] = "Ajustes visuales por defecto para todas las filas de habilidades. Las filas individuales pueden anular la forma de los iconos en sus propias pestañas."
L["Tip: Install the Masque addon to reskin ability icons with custom button styles."] = "Consejo: instala el complemento Masque para reskinear los iconos de habilidad con estilos de botón personalizados."
L["Shape"] = "Forma"
L["Default icon shape for all ability rows. Individual rows can override this in their own settings. Aura Tracker has its own setting under Bars."] = "Forma de icono por defecto para todas las filas de habilidades. Las filas individuales pueden anular esto en sus propios ajustes. El Rastreador de auras tiene su propio ajuste en Barras."
L["Spacing"] = "Espaciado"
L["Icon Spacing"] = "Espaciado de iconos"
L["The horizontal gap in pixels between each ability icon within a row. A small gap (2-4) helps visually separate icons. Set to 0 for icons to touch. Negative values allow overlap, which may look better with certain skins."] = "El espacio horizontal en píxeles entre cada icono de habilidad dentro de una fila. Un espacio pequeño (2-4) ayuda a separar visualmente los iconos. Pon 0 para que los iconos se toquen. Los valores negativos permiten solapamiento, que puede quedar mejor con ciertos skins."
L["Flow Row Spacing"] = "Espaciado de fila fluida"
L["When a row uses flow layout and icons overflow to a second line, this is the vertical gap between lines."] = "Cuando una fila usa disposición fluida y los iconos se desbordan a una segunda línea, este es el espacio vertical entre líneas."
L["Opacity"] = "Opacidad"
L["Ready Opacity"] = "Opacidad de listo"
L["How visible icons are when the ability is ready to use. 100% means fully visible, lower values make ready abilities slightly transparent. Most people want this at 100%."] = "Cuán visibles son los iconos cuando la habilidad está lista para usarse. 100% significa totalmente visible, los valores más bajos hacen las habilidades listas algo transparentes. La mayoría lo prefiere al 100%."
L["Cooldown Opacity"] = "Opacidad en reutilización"
L["How visible icons are when on cooldown (for rows with Dim On Cooldown enabled). A lower value (like 30%) makes cooldown abilities fade out so you can focus on what's ready. Higher values keep them visible."] = "Cuán visibles son los iconos cuando están en tiempo de reutilización (para filas con Atenuar en reutilización activado). Un valor más bajo (como 30%) atenúa las habilidades en reutilización para que puedas centrarte en lo que está listo. Los valores más altos las mantienen visibles."
L["Grey Out Unusable"] = "Atenuar inutilizables"
L["Makes icons grey when you don't have enough mana, rage, or energy to use the ability, or when you're in the wrong stance. Works the same way as WoW's default action bars.\n\nAutomatically disabled while resting in an inn or city to avoid constant grey-outs on combat abilities."] = "Vuelve grises los iconos cuando no tienes suficiente maná, furia o energía para usar la habilidad, o cuando estás en la actitud equivocada. Funciona igual que las barras de acción por defecto de WoW.\n\nSe desactiva automáticamente mientras descansas en una posada o ciudad para evitar atenuaciones constantes en las habilidades de combate."
L["Cooldowns"] = "Tiempos de reutilización"
L["How cooldown information is displayed on ability icons."] = "Cómo se muestra la información de tiempo de reutilización en los iconos de habilidad."
L["Display"] = "Visualización"
L["Cooldown Text"] = "Texto de reutilización"
L["Displays the remaining cooldown time as numbers on top of each icon. When enabled, VeevHUD shows its own text and hides text from addons like OmniCC. Select which rows display cooldown text."] = "Muestra el tiempo de reutilización restante como números sobre cada icono. Cuando está activado, VeevHUD muestra su propio texto y oculta el de complementos como OmniCC. Selecciona qué filas muestran el texto de reutilización."
L["Text outline style for ability icon text (cooldowns, stacks, charges, keybinds)."] = "Estilo de contorno de texto para el texto de los iconos de habilidad (reutilizaciones, acumulaciones, cargas, atajos)."
L["Minutes Threshold"] = "Umbral de minutos"
L["Remaining times above this many minutes are shown compactly. At the default of 2, 3 minutes 27 seconds is shown as 3m, while 1 minute 45 seconds is shown as 1:45."] = "Los tiempos restantes por encima de estos minutos se muestran de forma compacta. Con el valor por defecto de 2, 3 minutos 27 segundos se muestra como 3m, mientras que 1 minuto 45 segundos se muestra como 1:45."
L["Decimal Threshold"] = "Umbral de decimales"
L["Remaining times below this many seconds are shown with one decimal. At the default of 2, 3.4 seconds is shown as 3, while 1.8 seconds is shown as 1.8."] = "Los tiempos restantes por debajo de estos segundos se muestran con un decimal. Con el valor por defecto de 2, 3.4 segundos se muestra como 3, mientras que 1.8 segundos se muestra como 1.8."
L["Cooldown Spiral"] = "Espiral de reutilización"
L["Shows the dark 'clock sweep' overlay on abilities that are on cooldown. This visual helps you see at a glance how much time remains. Select which rows display the cooldown spiral."] = "Muestra la superposición oscura de 'barrido de reloj' en las habilidades que están en tiempo de reutilización. Este recurso visual te ayuda a ver de un vistazo cuánto tiempo queda. Selecciona qué filas muestran la espiral de reutilización."
L["Show GCD"] = "Mostrar GCD"
L["Controls which rows display the Global Cooldown (GCD) spinner. The GCD is the brief ~1.5 second lockout after using most abilities. Showing GCD helps you see when you can press your next ability."] = "Controla qué filas muestran el indicador del tiempo de reutilización global (GCD). El GCD es el breve bloqueo de ~1.5 segundos tras usar la mayoría de habilidades. Mostrar el GCD te ayuda a ver cuándo puedes pulsar tu siguiente habilidad."
L["Behavior"] = "Comportamiento"
L["Dim On Cooldown"] = "Atenuar en reutilización"
L["Controls which rows fade out (become transparent) when abilities are on cooldown. The amount they fade is controlled by the |cffffffffCooldown Opacity|r setting.\n\nRows without dimming stay at full brightness and use greying-out to indicate unavailability instead. Many players keep the Primary row undimmed so their core rotation stays visually prominent."] = "Controla qué filas se atenúan (se vuelven transparentes) cuando las habilidades están en tiempo de reutilización. La cantidad de atenuación la controla el ajuste |cffffffffOpacidad en reutilización|r.\n\nLas filas sin atenuación se mantienen con el brillo completo y usan el atenuado a gris para indicar la indisponibilidad. Muchos jugadores mantienen la fila primaria sin atenuar para que su rotación básica siga destacando visualmente."
L["Cooldown Sparkle"] = "Destello de reutilización"
L["Plays WoW's native sparkle animation when a cooldown finishes. Also triggers after the GCD, matching default action bar behavior. This is purely cooldown-based — it does not check resources or other usability conditions."] = "Reproduce la animación de destello nativa de WoW cuando termina un tiempo de reutilización. También se activa tras el GCD, igual que las barras de acción por defecto. Se basa únicamente en el tiempo de reutilización; no comprueba recursos ni otras condiciones de uso."
L["Cooldown Spiral Opacity"] = "Opacidad de espiral de reutilización"
L["How dark the spiral overlay appears during ability cooldowns. Lower values make it more subtle and transparent.\n\nNote: Even at 100%, the spiral won't completely obscure the icon — WoW's cooldown texture has built-in transparency."] = "Cuán oscura aparece la superposición en espiral durante los tiempos de reutilización de habilidades. Los valores más bajos la hacen más sutil y transparente.\n\nNota: incluso al 100%, la espiral no ocultará por completo el icono; la textura de reutilización de WoW tiene transparencia incorporada."
L["Resources"] = "Recursos"
L["How resource costs (mana, rage, energy) are shown on ability icons."] = "Cómo se muestran los costes de recurso (maná, furia, energía) en los iconos de habilidad."
L["Display Mode"] = "Modo de visualización"
L["How ability icons show whether you can afford to cast them:\n\n|cffffffffPrediction|r — Extends the cooldown sweep to include resource regeneration time. The icon shows how long until you can actually cast, accounting for both cooldown and resource cost. Energy and Mana predictions are tick-aware and very accurate. Rage falls back to Fill since rage income is unpredictable.\n\n|cffffffffFill|r — Darkens the icon from top to bottom proportional to missing resources. Simple and easy to read.\n\n|cffffffffBar|r — Shows a small colored bar at the bottom of each icon that fills up as you gain resources."] = "Cómo muestran los iconos de habilidad si puedes permitirte lanzarlas:\n\n|cffffffffPredicción|r — Extiende el barrido de reutilización para incluir el tiempo de regeneración de recurso. El icono muestra cuánto falta para que puedas lanzarla realmente, teniendo en cuenta tanto el tiempo de reutilización como el coste de recurso. Las predicciones de energía y maná tienen en cuenta los ticks y son muy precisas. La furia recurre a Relleno porque su generación es impredecible.\n\n|cffffffffRelleno|r — Oscurece el icono de arriba abajo en proporción a los recursos que faltan. Sencillo y fácil de leer.\n\n|cffffffffBarra|r — Muestra una pequeña barra de color en la parte inferior de cada icono que se llena a medida que ganas recursos."
L["Show On Rows"] = "Mostrar en filas"
L["Choose which rows show resource cost information on their icons. When enabled, you can see at a glance whether you have enough mana, rage, or energy to cast each ability."] = "Elige qué filas muestran la información de coste de recurso en sus iconos. Cuando está activado, puedes ver de un vistazo si tienes suficiente maná, furia o energía para lanzar cada habilidad."
L["Show During Cooldowns"] = "Mostrar durante reutilizaciones"
L["Shows the resource cost overlay on icons while they are on cooldown, so you can see your resource state through the cooldown spiral. When disabled, the resource overlay only appears when the ability is off cooldown."] = "Muestra la superposición de coste de recurso en los iconos mientras están en tiempo de reutilización, para que puedas ver tu estado de recurso a través de la espiral. Cuando está desactivado, la superposición de recurso solo aparece cuando la habilidad no está en reutilización."
L["Fill Style"] = "Estilo de relleno"
L["Use Resource Color"] = "Usar color de recurso"
L["Uses your resource type color for the fill overlay — red for rage, blue for mana, yellow for energy — instead of the custom Fill Color."] = "Usa el color de tu tipo de recurso para la superposición de relleno — rojo para furia, azul para maná, amarillo para energía — en lugar del color de relleno personalizado."
L["Fill Color"] = "Color de relleno"
L["The color of the resource cost fill overlay on icons. Default is black (a dark overlay showing missing resources). Only used when Use Resource Color is unchecked."] = "El color de la superposición de relleno de coste de recurso en los iconos. El valor por defecto es negro (una superposición oscura que muestra los recursos que faltan). Solo se usa cuando Usar color de recurso está desmarcado."
L["Fill Opacity"] = "Opacidad de relleno"
L["How opaque the resource cost overlay appears on icons. Higher values make it more obvious when you can't afford an ability. Applies to Fill mode and Prediction mode's fill fallback (used for rage and when predictions are unavailable)."] = "Cuán opaca aparece la superposición de coste de recurso en los iconos. Los valores más altos la hacen más evidente cuando no puedes permitirte una habilidad. Se aplica al modo Relleno y al relleno de reserva del modo Predicción (usado para la furia y cuando las predicciones no están disponibles)."
L["Invert Fill"] = "Invertir relleno"
L["Inverts the fill direction. Normal: overlay covers from top down showing missing resources. Inverted: overlay fills from bottom up showing current resources."] = "Invierte la dirección del relleno. Normal: la superposición cubre de arriba abajo mostrando los recursos que faltan. Invertido: la superposición se llena de abajo arriba mostrando los recursos actuales."
L["Bar Style"] = "Estilo de barra"
L["Uses your resource type color for the bar — red for rage, blue for mana, yellow for energy — instead of the custom Bar Color."] = "Usa el color de tu tipo de recurso para la barra — rojo para furia, azul para maná, amarillo para energía — en lugar del color de barra personalizado."
L["Bar Color"] = "Color de barra"
L["The color of the resource bar at the bottom of icons. Only used when Use Resource Color is unchecked."] = "El color de la barra de recurso en la parte inferior de los iconos. Solo se usa cuando Usar color de recurso está desmarcado."
L["Bar Height"] = "Altura de barra"
L["Height of the small resource bar shown at the bottom of each icon. Only visible when Display Mode is set to |cffffffffBar|r."] = "Altura de la pequeña barra de recurso que se muestra en la parte inferior de cada icono. Solo visible cuando el modo de visualización está en |cffffffffBarra|r."
L["Effects"] = "Efectos"
L["Visual effects on ability icons for active buffs, debuffs, and procs."] = "Efectos visuales en los iconos de habilidad para beneficios, perjuicios y procs activos."
L["Aura Tracking"] = "Rastreo de auras"
L["Abilities that apply buffs or debuffs (like Intimidating Shout, Rend, Renew) show the active duration with a glow while the effect is on a target. After it expires, the cooldown is shown. Disable if you only want to see cooldowns."] = "Las habilidades que aplican beneficios o perjuicios (como Grito intimidatorio, Desgarrar o Renovar) muestran la duración activa con un resplandor mientras el efecto está en un objetivo. Tras expirar, se muestra el tiempo de reutilización. Desactívalo si solo quieres ver los tiempos de reutilización."
L["Target-of-Target Support"] = "Compatibilidad con objetivo del objetivo"
L["Also check for your buffs and debuffs on your target's target. Useful for healers tracking HoTs on the tank's target.\n\nExamples:\n- Target the boss, see your heals on the tank (the boss's target)\n- Target the tank, see your DoTs on the boss (the tank's target)"] = "Comprueba también tus beneficios y perjuicios en el objetivo de tu objetivo. Útil para sanadores que rastrean HoT en el objetivo del tanque.\n\nEjemplos:\n- Selecciona al jefe y ve tus sanaciones en el tanque (el objetivo del jefe).\n- Selecciona al tanque y ve tus DoT en el jefe (el objetivo del tanque)."
L["Aura Spiral Opacity"] = "Opacidad de espiral de aura"
L["How dark the spiral overlay appears when tracking active buff or aura durations on icons. Lower values make it more subtle and transparent.\n\nNote: Even at 100%, the spiral won't completely obscure the icon — WoW's cooldown texture has built-in transparency."] = "Cuán oscura aparece la superposición en espiral al rastrear las duraciones de beneficios o auras activos en los iconos. Los valores más bajos la hacen más sutil y transparente.\n\nNota: incluso al 100%, la espiral no ocultará por completo el icono; la textura de reutilización de WoW tiene transparencia incorporada."
L["Cast Feedback"] = "Respuesta de lanzamiento"
L["Plays a brief 'pop' animation (the icon scales up slightly then back down) whenever you successfully cast an ability. Gives satisfying visual feedback that your spell went off. Select which rows show this animation."] = "Reproduce una breve animación de 'pop' (el icono se agranda ligeramente y vuelve a su tamaño) cada vez que lanzas con éxito una habilidad. Da una respuesta visual satisfactoria de que tu hechizo se ejecutó. Selecciona qué filas muestran esta animación."
L["Pop Scale"] = "Escala de pop"
L["How much the icon briefly grows when you cast a spell. Higher values = bigger pop."] = "Cuánto crece brevemente el icono cuando lanzas un hechizo. Valores más altos = pop más grande."
L["Ready Glow"] = "Resplandor de listo"
L["Shows a glowing border around ability icons when they come off cooldown and are ready to use. Only triggers while in combat. Select which rows display this effect."] = "Muestra un borde resplandeciente alrededor de los iconos de habilidad cuando salen del tiempo de reutilización y están listos para usarse. Solo se activa en combate. Selecciona qué filas muestran este efecto."
L["Re-trigger Glow"] = "Reactivar resplandor"
L["Which rows re-trigger the glow whenever an ability becomes usable again (not just the first time).\n\nOn these rows, the glow plays again every time usability changes (e.g., gaining enough resources, target entering Execute range). Rows not selected here play the glow only once per cooldown cycle.\n\nNote: Reactive abilities (like Execute or Overpower) always re-trigger regardless of this setting."] = "Qué filas reactivan el resplandor cada vez que una habilidad vuelve a ser utilizable (no solo la primera vez).\n\nEn estas filas, el resplandor se reproduce de nuevo cada vez que cambia la posibilidad de uso (p. ej., al ganar suficientes recursos o cuando el objetivo entra en rango de Ejecutar). Las filas no seleccionadas aquí reproducen el resplandor solo una vez por ciclo de reutilización.\n\nNota: las habilidades reactivas (como Ejecutar o Arrollar) siempre se reactivan sin importar este ajuste."
L["Duration"] = "Duración"
L["How long each ready glow animation lasts (in seconds). After this time, the glow fades out. On rows with Re-trigger Glow, the glow will re-trigger at this interval each time usability changes."] = "Cuánto dura cada animación de resplandor de listo (en segundos). Tras este tiempo, el resplandor se desvanece. En las filas con Reactivar resplandor, el resplandor se reactivará a este intervalo cada vez que cambie la posibilidad de uso."
L["Pre-trigger Time"] = "Tiempo de preactivación"
L["Begin the glow this many seconds before the cooldown completes, so you can prepare your next action. At 0, the glow only appears once the cooldown is fully complete."] = "Inicia el resplandor estos segundos antes de que se complete el tiempo de reutilización, para que puedas preparar tu siguiente acción. Con 0, el resplandor solo aparece cuando el tiempo de reutilización se completa por completo."
L["Queued Highlight"] = "Resaltado en cola"
L["Brightens the icon of your next queued ability. Most noticeable on \"next melee\" attacks like Heroic Strike or Maul that stay queued until your next swing, but you may also see a brief flash on any ability queued during a cast or GCD."] = "Ilumina el icono de tu siguiente habilidad en cola. Más perceptible en ataques de \"siguiente cuerpo a cuerpo\" como Golpe heroico o Mazazo, que permanecen en cola hasta tu siguiente golpe, pero también puedes ver un breve destello en cualquier habilidad puesta en cola durante un lanzamiento o el GCD."
L["Indicators"] = "Indicadores"
L["Range checking, sorting, and keybind display on ability icons."] = "Comprobación de alcance, ordenación y visualización de atajos en los iconos de habilidad."
L["Range Indicator"] = "Indicador de alcance"
L["Shows a red overlay on spell icons when your current target is out of range. Shows when an ability is usable but out of range — even during cooldown, giving you a heads-up on positioning. When resources are insufficient, the grey/resource indicators take priority instead.\n\nNote: Only shows when you have a target. Spells without a range component (self-buffs, etc.) are not affected."] = "Muestra una superposición roja en los iconos de hechizo cuando tu objetivo actual está fuera de alcance. Aparece cuando una habilidad es utilizable pero está fuera de alcance — incluso durante el tiempo de reutilización, avisándote sobre tu posición. Cuando los recursos son insuficientes, los indicadores de gris/recurso tienen prioridad.\n\nNota: solo se muestra cuando tienes un objetivo. Los hechizos sin componente de alcance (autobeneficios, etc.) no se ven afectados."
L["Dynamic Sorting"] = "Ordenación dinámica"
L["Automatically reorders icons left-to-right by remaining cooldown, so abilities that are almost ready appear first.\n\nUseful for DOT classes (see which debuff is closest to expiring) and cooldown-heavy classes (see which ability is ready next).\n\nTie-breaker: When multiple abilities are ready, they sort by their original row position — so your row order acts as a priority list and the leftmost icon is always the next best spell to cast."] = "Reordena automáticamente los iconos de izquierda a derecha por el tiempo de reutilización restante, de modo que las habilidades casi listas aparecen primero.\n\nÚtil para clases con DoT (ver qué perjuicio está más cerca de expirar) y clases con muchos tiempos de reutilización (ver qué habilidad estará lista a continuación).\n\nDesempate: cuando hay varias habilidades listas, se ordenan por su posición original en la fila; así, el orden de tus filas actúa como lista de prioridades y el icono más a la izquierda es siempre el mejor hechizo que lanzar a continuación."
L["Smooth Sorting"] = "Ordenación suave"
L["Icons slide smoothly into their new position when the sort order changes. Disable for instant repositioning."] = "Los iconos se deslizan con suavidad a su nueva posición cuando cambia el orden. Desactívalo para un reposicionamiento instantáneo."
L["Keybinds"] = "Atajos de teclado"
L["Displays the keyboard shortcut for each ability in the bottom-right corner. VeevHUD scans your action bars to find where each spell is placed. Modifiers are abbreviated: Shift=S, Ctrl=C, Alt=A (e.g., Shift+X becomes 'SX').\n\nSupports Bartender4, ElvUI, Dominos. If you move spells or change keybinds, the display updates automatically."] = "Muestra el atajo de teclado de cada habilidad en la esquina inferior derecha. VeevHUD escanea tus barras de acción para encontrar dónde está colocado cada hechizo. Los modificadores se abrevian: Mayús=S, Ctrl=C, Alt=A (p. ej., Mayús+X se convierte en 'SX').\n\nCompatible con Bartender4, ElvUI y Dominos. Si mueves hechizos o cambias atajos, la visualización se actualiza automáticamente."
L["Text Size"] = "Tamaño del texto"
L["The font size for keybind text in pixels. Larger values make the text more readable but take up more space on the icon."] = "El tamaño de fuente del texto de atajos en píxeles. Los valores más grandes hacen el texto más legible pero ocupan más espacio en el icono."
L["Item Counts"] = "Contadores de objetos"
L["Reagent Count"] = "Contador de componentes"
L["Shows the number of reagents you have in the top-right corner of spell icons that consume reagents on cast. Examples: Soul Shards on warlock abilities, seeds on Rebirth, Flash Powder on Vanish, Ankhs on Reincarnation."] = "Muestra la cantidad de componentes que tienes en la esquina superior derecha de los iconos de hechizo que consumen componentes al lanzarse. Ejemplos: Fragmentos de alma en habilidades de brujo, semillas en Renacer, Polvo de destello en Esfumarse, Anj en Reencarnación."
L["Count All Ranks"] = "Contar todos los rangos"
L["When enabled, counts reagents for all spell ranks combined (e.g., all seed types for Rebirth). When disabled, only counts the reagent for your highest learned rank."] = "Cuando está activado, cuenta los componentes de todos los rangos del hechizo combinados (p. ej., todos los tipos de semilla para Renacer). Cuando está desactivado, solo cuenta el componente de tu rango aprendido más alto."
L["Consumable Count"] = "Contador de consumibles"
L["Shows your current bag count in the top-right corner of consumable icons (potions, runes, etc.)."] = "Muestra la cantidad actual en tu mochila en la esquina superior derecha de los iconos de consumible (pociones, runas, etc.)."
L["Status Bars"] = "Barras de estado"
L["Resource Bar"] = "Barra de recurso"
L["Your character's resource bar (mana, rage, or energy)."] = "La barra de recurso de tu personaje (maná, furia o energía)."
L["Shows a bar displaying your current mana, rage, or energy (depending on your class). Appears between the health bar and the ability icon rows."] = "Muestra una barra con tu maná, furia o energía actual (según tu clase). Aparece entre la barra de salud y las filas de iconos de habilidad."
L["Width"] = "Anchura"
L["How wide the resource bar is in pixels."] = "La anchura de la barra de recurso en píxeles."
L["Height"] = "Altura"
L["How tall/thick the resource bar is in pixels. Changing this will automatically adjust the position of elements above it."] = "La altura/grosor de la barra de recurso en píxeles. Cambiar esto ajustará automáticamente la posición de los elementos situados encima."
L["Text"] = "Texto"
L["Text Format"] = "Formato de texto"
L["Controls what text is shown on the resource bar.\n\n|cffffffffCurrent|r — Shows your actual resource (e.g., 4523).\n|cffffffffPercent|r — Shows your resource percentage (e.g., 85%).\n|cffffffffBoth|r — Shows both (e.g., 4523 (85%)).\n|cffffffffCurrent / Max|r — Shows current and maximum (e.g., 4523 / 5320).\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage (e.g., 4523 / 5320 (85%)).\n|cffffffffDeficit|r — Shows how much is missing (e.g., -797). Hidden at full.\n|cffffffffNone|r — Hides the text entirely."] = "Controla qué texto se muestra en la barra de recurso.\n\n|cffffffffActual|r — Muestra tu recurso real (p. ej., 4523).\n|cffffffffPorcentaje|r — Muestra el porcentaje de recurso (p. ej., 85%).\n|cffffffffAmbos|r — Muestra ambos (p. ej., 4523 (85%)).\n|cffffffffActual / Máx.|r — Muestra el actual y el máximo (p. ej., 4523 / 5320).\n|cffffffffActual / Máx. (%)|r — Muestra el actual, el máximo y el porcentaje (p. ej., 4523 / 5320 (85%)).\n|cffffffffDéficit|r — Muestra cuánto falta (p. ej., -797). Oculto al máximo.\n|cffffffffNinguno|r — Oculta el texto por completo."
L["Number Format"] = "Formato de números"
L["Controls how numbers are displayed.\n\n|cffffffffAbbreviated|r — Large numbers shortened (e.g., 4.5k, 1.2m).\n|cffffffffFull|r — Whole numbers (e.g., 4523).\n|cffffffffComma|r — Comma-separated (e.g., 4,523)."] = "Controla cómo se muestran los números.\n\n|cffffffffAbreviado|r — Números grandes acortados (p. ej., 4.5k, 1.2m).\n|cffffffffCompleto|r — Números enteros (p. ej., 4523).\n|cffffffffCon coma|r — Separados por comas (p. ej., 4,523)."
L["Font size for the resource text. Larger sizes are easier to read but may overflow small bars."] = "Tamaño de fuente del texto de recurso. Los tamaños más grandes son más fáciles de leer pero pueden desbordar las barras pequeñas."
L["Text outline style for the resource bar."] = "Estilo de contorno de texto para la barra de recurso."
L["Default Color"] = "Color por defecto"
L["Colors the bar based on your resource type — blue for mana, red for rage, yellow for energy. Uncheck to use a custom color instead.\n\n"] = "Colorea la barra según tu tipo de recurso — azul para maná, rojo para furia, amarillo para energía. Desmarca para usar un color personalizado.\n\n"
L["Overridden by Innervate Highlight (mana) and Rage Highlight (rage) when those are active."] = "Anulado por Resaltado de Vigorizar (maná) y Resaltado de furia (furia) cuando están activos."
L["The custom color for the resource bar. Only used when Use Resource Color is unchecked.\n\n"] = "El color personalizado para la barra de recurso. Solo se usa cuando Usar color de recurso está desmarcado.\n\n"
L["Innervate Highlight"] = "Resaltado de Vigorizar"
L["Changes the mana bar color when the Innervate buff is active, giving you immediate visual feedback that your mana regeneration is boosted."] = "Cambia el color de la barra de maná cuando el beneficio Vigorizar está activo, dándote una respuesta visual inmediata de que tu regeneración de maná está potenciada."
L["Color"] = "Color"
L["The color the resource bar changes to during Innervate."] = "El color al que cambia la barra de recurso durante Vigorizar."
L["Master toggle for rage bar coloring. When enabled, the bar changes color based on rage thresholds (e.g., flag rage cap risk) and when Heroic Strike or Cleave is queued onto your next swing."] = "Interruptor principal para el coloreado de la barra de furia. Cuando está activado, la barra cambia de color según los umbrales de furia (p. ej., para señalar el riesgo de tope de furia) y cuando Golpe heroico o Hender están en cola para tu siguiente golpe."
L["Rage Thresholds"] = "Umbrales de furia"
L["Threshold Coloring"] = "Coloreado por umbral"
L["Recolor the bar based on current rage. Three tiers (low/mid/high) gated by two thresholds."] = "Recolorea la barra según la furia actual. Tres niveles (bajo/medio/alto) delimitados por dos umbrales."
L["Low Threshold"] = "Umbral bajo"
L["Below this rage value, the bar uses the Low color. Above it (and below the High threshold), the Mid color."] = "Por debajo de este valor de furia, la barra usa el color bajo. Por encima (y por debajo del umbral alto), el color medio."
L["High Threshold"] = "Umbral alto"
L["At or above this rage value, the bar uses the High color (e.g., bright red to flag rage cap risk)."] = "En o por encima de este valor de furia, la barra usa el color alto (p. ej., rojo brillante para señalar el riesgo de tope de furia)."
L["Low Color"] = "Color bajo"
L["Bar color when rage is below the Low threshold."] = "Color de la barra cuando la furia está por debajo del umbral bajo."
L["Mid Color"] = "Color medio"
L["Bar color when rage is between the Low and High thresholds."] = "Color de la barra cuando la furia está entre los umbrales bajo y alto."
L["High Color"] = "Color alto"
L["Bar color when rage is at or above the High threshold."] = "Color de la barra cuando la furia está en o por encima del umbral alto."
L["Queued Ability Override"] = "Anulación por habilidad en cola"
L["Queue Override"] = "Anulación de cola"
L["When a swing-reset ability (Heroic Strike, Cleave, Maul) is queued onto your next swing, override the threshold color with a per-ability color."] = "Cuando una habilidad que reinicia el golpe (Golpe heroico, Hender, Mazazo) está en cola para tu siguiente golpe, anula el color de umbral con un color por habilidad."
L["Bar color when %s is queued onto your next swing."] = "Color de la barra cuando %s está en cola para tu siguiente golpe."
L["Rage Highlight"] = "Resaltado de furia"
L["Shows a bright highlight at the bar's current fill point — the glowing line where the filled and empty portions meet. Adds visual polish."] = "Muestra un resaltado brillante en el punto de relleno actual de la barra — la línea luminosa donde se encuentran las partes llena y vacía. Añade un toque visual."
L["How wide the spark highlight is in pixels. Larger values create a broader, more prominent glow."] = "La anchura del resaltado de destello en píxeles. Los valores más grandes crean un resplandor más ancho y prominente."
L["Overflow"] = "Desbordamiento"
L["How far the spark glow extends beyond the top and bottom edges of the bar (in pixels). Higher values create a taller spark that 'overflows' past the bar."] = "Cuánto se extiende el resplandor del destello más allá de los bordes superior e inferior de la barra (en píxeles). Los valores más altos crean un destello más alto que 'se desborda' de la barra."
L["Hide at Full/Empty"] = "Ocultar al máx./vacío"
L["Hides the spark when the bar is completely full or completely empty, since there's no meaningful fill point to highlight in those states."] = "Oculta el destello cuando la barra está completamente llena o completamente vacía, ya que no hay un punto de relleno relevante que resaltar en esos estados."
L["Overlays"] = "Superposiciones"
L["Predicted Cost"] = "Coste previsto"
L["Shows a darkened section on the resource bar representing the cost of abilities you are currently casting or have queued (e.g., Heroic Strike, Cleave). Gives you a preview of where your resource will be after the ability completes."] = "Muestra una sección oscurecida en la barra de recurso que representa el coste de las habilidades que estás lanzando o tienes en cola (p. ej., Golpe heroico, Hender). Te da una vista previa de dónde estará tu recurso una vez se complete la habilidad."
L["Energy Ticker"] = "Marcador de energía"
L["Shows progress toward the next energy tick (energy regenerates every 2 seconds). Helps you time abilities to maximize energy efficiency."] = "Muestra el progreso hacia el siguiente tick de energía (la energía se regenera cada 2 segundos). Te ayuda a sincronizar las habilidades para maximizar la eficiencia de energía."
L["Style"] = "Estilo"
L["|cffffffffTicker Bar|r — Shows a separate thin bar below the resource bar that fills as the next tick approaches.\n\n|cffffffffSpark|r — Shows a moving spark overlay on the resource bar itself, which is more subtle."] = "|cffffffffBarra de marcador|r — Muestra una barra fina separada bajo la barra de recurso que se llena a medida que se acerca el siguiente tick.\n\n|cffffffffDestello|r — Muestra una superposición de destello en movimiento sobre la propia barra de recurso, más sutil."
L["Show at Full Energy"] = "Mostrar con energía al máx."
L["Keep the tick indicator running even when at full energy. Useful for timing openers — you can see exactly when the next tick will occur and use energy right before it arrives."] = "Mantiene el indicador de tick en marcha incluso con la energía al máximo. Útil para sincronizar aperturas — puedes ver exactamente cuándo ocurrirá el siguiente tick y usar energía justo antes de que llegue."
L["Bar Settings"] = "Ajustes de barra"
L["How tall the energy ticker bar is in pixels."] = "La altura de la barra de marcador de energía en píxeles."
L["Bar Offset"] = "Desplazamiento de barra"
L["Moves the energy ticker bar up or down relative to the resource bar. Positive values move it down, negative values move it up."] = "Mueve la barra de marcador de energía hacia arriba o abajo respecto a la barra de recurso. Los valores positivos la mueven hacia abajo, los negativos hacia arriba."
L["The color used for the energy ticker bar."] = "El color usado para la barra de marcador de energía."
L["Spark Settings"] = "Ajustes de destello"
L["Spark Width"] = "Anchura de destello"
L["How wide the tick spark is in pixels."] = "La anchura del destello de tick en píxeles."
L["Spark Height"] = "Altura de destello"
L["How tall the tick spark is relative to the resource bar. Values above 1.0 make the spark extend beyond the bar edges."] = "La altura del destello de tick respecto a la barra de recurso. Los valores por encima de 1.0 hacen que el destello se extienda más allá de los bordes de la barra."
L["Mana Ticker"] = "Marcador de maná"
L["Shows a moving spark on the resource bar indicating when your next mana tick will arrive. Mana regenerates in periodic ticks, and casting at the wrong time can delay your next tick — this indicator helps you cast at the optimal moment."] = "Muestra un destello en movimiento sobre la barra de recurso que indica cuándo llegará tu siguiente tick de maná. El maná se regenera en ticks periódicos, y lanzar en el momento equivocado puede retrasar tu siguiente tick — este indicador te ayuda a lanzar en el momento óptimo."
L["|cffffffffOutside 5 Second Rule|r — Only shows the tick timer when you haven't cast a spell in the last 5 seconds (when you're getting full spirit-based mana regeneration).\n\n|cffffffffNext Full Tick|r (Recommended) — Always active. After you cast a spell, it predicts exactly when your first full-rate mana tick will arrive and counts down to it. Cast right after the tick completes to get the most mana before your next spell."] = "|cffffffffFuera de la regla de 5 segundos|r — Solo muestra el temporizador de tick cuando no has lanzado un hechizo en los últimos 5 segundos (cuando recibes la regeneración de maná completa basada en espíritu).\n\n|cffffffffSiguiente tick completo|r (recomendado) — Siempre activo. Tras lanzar un hechizo, predice exactamente cuándo llegará tu primer tick de maná a tasa completa y hace la cuenta atrás hasta él. Lanza justo después de que se complete el tick para obtener el máximo de maná antes de tu siguiente hechizo."
L["How wide the mana tick spark is in pixels."] = "La anchura del destello de tick de maná en píxeles."
L["How tall the mana tick spark is relative to the resource bar. Values above 1.0 make it extend beyond the bar edges."] = "La altura del destello de tick de maná respecto a la barra de recurso. Los valores por encima de 1.0 hacen que se extienda más allá de los bordes de la barra."
L["Mana Bar (Druid)"] = "Barra de maná (Druida)"
L["Shows a secondary mana bar below the resource bar while in Cat Form or Bear Form, so you can monitor mana for shifting and casting."] = "Muestra una barra de maná secundaria bajo la barra de recurso mientras estás en Forma de gato o Forma de oso, para que puedas controlar el maná al transformarte y lanzar."
L["Show a secondary mana bar below the resource bar while shapeshifted."] = "Muestra una barra de maná secundaria bajo la barra de recurso mientras estás transformado."
L["How tall the secondary mana bar is in pixels."] = "La altura de la barra de maná secundaria en píxeles."
L["Show Spark"] = "Mostrar destello"
L["Shows a glowing spark at the current fill position on the mana bar."] = "Muestra un destello luminoso en la posición de relleno actual de la barra de maná."
L["The color used for the secondary mana bar."] = "El color usado para la barra de maná secundaria."
L["Show Mana Ticker"] = "Mostrar marcador de maná"
L["Shows the mana tick spark on this bar while in form. When disabled, the mana ticker only appears on the main resource bar in caster form."] = "Muestra el destello de tick de maná en esta barra mientras estás en forma. Cuando está desactivado, el marcador de maná solo aparece en la barra de recurso principal en forma de lanzador."
L["Form Cost Marker"] = "Marcador de coste de forma"
L["Shows a vertical line on the mana bar when your mana is too low to re-enter your current shapeshift form. The line indicates the mana threshold needed, so you can see how close you are to being able to shift back."] = "Muestra una línea vertical en la barra de maná cuando tu maná es demasiado bajo para volver a entrar en tu forma de cambio de forma actual. La línea indica el umbral de maná necesario, para que veas cuán cerca estás de poder volver a transformarte."
L["Controls what text is shown on the Druid mana bar.\n\n|cffffffffCurrent|r — Shows your actual mana.\n|cffffffffPercent|r — Shows your mana percentage.\n|cffffffffBoth|r — Shows both.\n|cffffffffCurrent / Max|r — Shows current and maximum.\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage.\n|cffffffffDeficit|r — Shows how much is missing. Hidden at full.\n|cffffffffNone|r — Hides the text."] = "Controla qué texto se muestra en la barra de maná de Druida.\n\n|cffffffffActual|r — Muestra tu maná real.\n|cffffffffPorcentaje|r — Muestra tu porcentaje de maná.\n|cffffffffAmbos|r — Muestra ambos.\n|cffffffffActual / Máx.|r — Muestra el actual y el máximo.\n|cffffffffActual / Máx. (%)|r — Muestra el actual, el máximo y el porcentaje.\n|cffffffffDéficit|r — Muestra cuánto falta. Oculto al máximo.\n|cffffffffNinguno|r — Oculta el texto."
L["Controls how numbers are displayed."] = "Controla cómo se muestran los números."
L["Font size for the mana bar text."] = "Tamaño de fuente del texto de la barra de maná."
L["Text outline style for the druid mana bar."] = "Estilo de contorno de texto para la barra de maná de druida."
L["Health Bar"] = "Barra de salud"
L["Your character's health bar with heal prediction."] = "La barra de salud de tu personaje con predicción de sanación."
L["Shows a bar displaying your current health above the resource bar. Gives you a quick glance at your survivability without looking at your unit frame."] = "Muestra una barra con tu salud actual sobre la barra de recurso. Te da un vistazo rápido a tu supervivencia sin mirar tu marco de unidad."
L["How wide the health bar is in pixels."] = "La anchura de la barra de salud en píxeles."
L["How tall/thick the health bar is in pixels. Changing this will automatically adjust the position of elements above it."] = "La altura/grosor de la barra de salud en píxeles. Cambiar esto ajustará automáticamente la posición de los elementos situados encima."
L["Controls what text is shown on the health bar.\n\n|cffffffffCurrent|r — Shows your actual health (e.g., 3256).\n|cffffffffPercent|r — Shows your health percentage (e.g., 71%).\n|cffffffffBoth|r — Shows both (e.g., 3256 (71%)).\n|cffffffffCurrent / Max|r — Shows current and maximum (e.g., 3256 / 4580).\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage (e.g., 3256 / 4580 (71%)).\n|cffffffffDeficit|r — Shows how much health is missing (e.g., -1324). Hidden at full.\n|cffffffffNone|r — Hides the text entirely."] = "Controla qué texto se muestra en la barra de salud.\n\n|cffffffffActual|r — Muestra tu salud real (p. ej., 3256).\n|cffffffffPorcentaje|r — Muestra tu porcentaje de salud (p. ej., 71%).\n|cffffffffAmbos|r — Muestra ambos (p. ej., 3256 (71%)).\n|cffffffffActual / Máx.|r — Muestra el actual y el máximo (p. ej., 3256 / 4580).\n|cffffffffActual / Máx. (%)|r — Muestra el actual, el máximo y el porcentaje (p. ej., 3256 / 4580 (71%)).\n|cffffffffDéficit|r — Muestra cuánta salud falta (p. ej., -1324). Oculto al máximo.\n|cffffffffNinguno|r — Oculta el texto por completo."
L["Font size for the health text. Larger sizes are easier to read but may overflow small bars."] = "Tamaño de fuente del texto de salud. Los tamaños más grandes son más fáciles de leer pero pueden desbordar las barras pequeñas."
L["Text outline style for the health bar."] = "Estilo de contorno de texto para la barra de salud."
L["Use Class Color"] = "Usar color de clase"
L["Colors the health bar using your class color (e.g., brown for Warriors, purple for Warlocks) instead of the standard green."] = "Colorea la barra de salud con el color de tu clase (p. ej., marrón para Guerreros, morado para Brujos) en lugar del verde estándar."
L["The custom color for the health bar. Only used when Use Class Color is unchecked."] = "El color personalizado para la barra de salud. Solo se usa cuando Usar color de clase está desmarcado."
L["Heal Prediction"] = "Predicción de sanación"
L["Shows a lighter overlay on the health bar representing incoming heals. The overlay extends from your current health into the missing health area, giving you a preview of where your health will be after heals land."] = "Muestra una superposición más clara en la barra de salud que representa las sanaciones entrantes. La superposición se extiende desde tu salud actual hacia la zona de salud que falta, dándote una vista previa de dónde estará tu salud cuando lleguen las sanaciones."
L["Pet Health Bar"] = "Barra de salud de mascota"
L["Your pet's health bar. Automatically hides when no pet is active."] = "La barra de salud de tu mascota. Se oculta automáticamente cuando no hay ninguna mascota activa."
L["Shows a bar displaying your pet's current health. Automatically hides when you have no active pet."] = "Muestra una barra con la salud actual de tu mascota. Se oculta automáticamente cuando no tienes ninguna mascota activa."
L["How wide the pet health bar is in pixels."] = "La anchura de la barra de salud de mascota en píxeles."
L["How tall/thick the pet health bar is in pixels."] = "La altura/grosor de la barra de salud de mascota en píxeles."
L["Controls what text is shown on the pet health bar.\n\n|cffffffffCurrent|r — Shows actual health.\n|cffffffffPercent|r — Shows health percentage.\n|cffffffffBoth|r — Shows both.\n|cffffffffCurrent / Max|r — Shows current and maximum.\n|cffffffffCurrent / Max (%)|r — Shows current, maximum, and percentage.\n|cffffffffDeficit|r — Shows how much health is missing. Hidden at full.\n|cffffffffNone|r — Hides the text."] = "Controla qué texto se muestra en la barra de salud de mascota.\n\n|cffffffffActual|r — Muestra la salud real.\n|cffffffffPorcentaje|r — Muestra el porcentaje de salud.\n|cffffffffAmbos|r — Muestra ambos.\n|cffffffffActual / Máx.|r — Muestra el actual y el máximo.\n|cffffffffActual / Máx. (%)|r — Muestra el actual, el máximo y el porcentaje.\n|cffffffffDéficit|r — Muestra cuánta salud falta. Oculto al máximo.\n|cffffffffNinguno|r — Oculta el texto."
L["Font size for the pet health text."] = "Tamaño de fuente del texto de salud de mascota."
L["Text outline style for the pet health bar."] = "Estilo de contorno de texto para la barra de salud de mascota."
L["The color for the pet health bar."] = "El color de la barra de salud de mascota."
L["Shows a lighter overlay on the pet health bar representing incoming heals."] = "Muestra una superposición más clara en la barra de salud de mascota que representa las sanaciones entrantes."
L["Combo Points"] = "Puntos de combo"
L["Horizontal combo point display below the resource bar."] = "Visualización horizontal de puntos de combo bajo la barra de recurso."
L["Shows combo point bars below the resource bar. For Druids, this only appears while in Cat Form."] = "Muestra barras de puntos de combo bajo la barra de recurso. Para los Druidas, esto solo aparece mientras están en Forma de gato."
L["Size & Layout"] = "Tamaño y disposición"
L["The total width of the combo points display in pixels."] = "La anchura total de la visualización de puntos de combo en píxeles."
L["The height of each combo point bar in pixels. Smaller values create a more subtle display."] = "La altura de cada barra de punto de combo en píxeles. Los valores más pequeños crean una visualización más sutil."
L["Bar Spacing"] = "Espaciado de barras"
L["The gap in pixels between each individual combo point segment."] = "El espacio en píxeles entre cada segmento individual de punto de combo."
L["The color used for active combo point segments."] = "El color usado para los segmentos de punto de combo activos."
L["Aura Tracker"] = "Rastreador de auras"
L["The Aura Tracker shows small icons for important temporary buffs — class procs (Enrage, Flurry, Clearcasting), external buffs (Bloodlust, Power Infusion, Innervate), and any custom auras you add.\n\nUse the tabs above to configure which auras to show."] = "El Rastreador de auras muestra iconos pequeños para los beneficios temporales importantes — procs de clase (Enfurecer, Frenesí, Lanzamiento puro), beneficios externos (Ansia de sangre, Infusión de poder, Vigorizar) y cualquier aura personalizada que añadas.\n\nUsa las pestañas de arriba para configurar qué auras mostrar."
L["Enable Aura Tracker"] = "Activar Rastreador de auras"
L["Master toggle for the Aura Tracker feature. When disabled, no aura icons will be shown."] = "Interruptor principal para la función del Rastreador de auras. Cuando está desactivado, no se mostrará ningún icono de aura."
L["Layout"] = "Disposición"
L["How big the aura icons are in pixels. These are typically smaller than ability icons since they're just indicators. 20-28 pixels works well for most people."] = "El tamaño de los iconos de aura en píxeles. Suelen ser más pequeños que los iconos de habilidad, ya que son meros indicadores. 20-28 píxeles funciona bien para la mayoría."
L["The gap in pixels between each aura icon when multiple auras are active at once."] = "El espacio en píxeles entre cada icono de aura cuando hay varias auras activas a la vez."
L["Makes aura icons shorter by shrinking height while keeping width the same. Useful if you want compact spell rows but prefer aura icons to stay more square and readable."] = "Hace los iconos de aura más bajos reduciendo la altura sin cambiar la anchura. Útil si quieres filas de hechizos compactas pero prefieres que los iconos de aura se mantengan más cuadrados y legibles."
L["Glow"] = "Resplandor"
L["Edge Glow"] = "Resplandor de borde"
L["Shows a glowing animated border around active aura icons, making them stand out and drawing your eye to important buffs."] = "Muestra un borde animado luminoso alrededor de los iconos de aura activos, haciéndolos destacar y atrayendo tu vista hacia los beneficios importantes."
L["Backdrop Intensity"] = "Intensidad de fondo"
L["Controls the brightness of the soft colored halo that appears behind each aura icon. Higher values make the glow more prominent. Set to 0 to turn it off completely."] = "Controla el brillo del suave halo de color que aparece detrás de cada icono de aura. Los valores más altos hacen el resplandor más prominente. Pon 0 para desactivarlo por completo."
L["Backdrop Size"] = "Tamaño de fondo"
L["How far the backdrop glow extends outward from each aura icon. Larger values create a wider, softer halo."] = "Cuánto se extiende el resplandor de fondo hacia fuera desde cada icono de aura. Los valores más grandes crean un halo más ancho y suave."
L["Animation"] = "Animación"
L["Show Duration"] = "Mostrar duración"
L["Displays the remaining time on aura buffs as text on the icon. Disable if you prefer a cleaner look or if it overlaps with stack counts."] = "Muestra el tiempo restante de los beneficios de aura como texto en el icono. Desactívalo si prefieres un aspecto más limpio o si se solapa con los contadores de acumulación."
L["Text outline style for aura tracker text."] = "Estilo de contorno de texto para el texto del rastreador de auras."
L["Slide Animation"] = "Animación de deslizamiento"
L["When auras appear or disappear, the remaining icons smoothly slide to re-center instead of snapping instantly. Disable for instant repositioning."] = "Cuando las auras aparecen o desaparecen, los iconos restantes se deslizan con suavidad para recentrarse en lugar de hacerlo de golpe. Desactívalo para un reposicionamiento instantáneo."
L["Activation Pop"] = "Pop de activación"
L["How much the icon briefly grows when an aura activates or refreshes. Set to 100% to disable the pop animation."] = "Cuánto crece brevemente el icono cuando un aura se activa o se renueva. Pon 100% para desactivar la animación de pop."
L["Sort Order"] = "Orden"
L["How active aura icons are arranged.\n\n|cffffffffActivation Order|r — First-activated aura appears on the left, newest on the right.\n\n|cffffffffFixed|r — Icons stay in a consistent order based on spell registration (class procs first, then externals, then custom).\n\n|cffffffffLeast Remaining|r — Aura closest to expiring appears on the left. Icons re-sort as durations tick down."] = "Cómo se ordenan los iconos de aura activos.\n\n|cffffffffOrden de activación|r — El aura activada primero aparece a la izquierda, la más reciente a la derecha.\n\n|cffffffffFijo|r — Los iconos se mantienen en un orden constante basado en el registro de hechizos (primero los procs de clase, luego los externos, luego los personalizados).\n\n|cffffffffMenos restante|r — El aura más próxima a expirar aparece a la izquierda. Los iconos se reordenan a medida que las duraciones descienden."
L["Activation Order"] = "Orden de activación"
L["Fixed"] = "Fijo"
L["Least Remaining"] = "Menos restante"
L["Bars"] = "Barras"
L["Auras set to \"Bar\" mode (via the Display dropdown in the aura list tabs) render as a vertical stack of timer bars below the icon row. These settings control how those bars look."] = "Las auras configuradas en modo \"Barra\" (mediante el menú Visualización en las pestañas de la lista de auras) se muestran como una pila vertical de barras de temporizador bajo la fila de iconos. Estos ajustes controlan el aspecto de esas barras."
L["Bar Width"] = "Anchura de barra"
L["Width of each timer bar in pixels."] = "Anchura de cada barra de temporizador en píxeles."
L["Height of each timer bar in pixels. The spell icon is sized to match."] = "Altura de cada barra de temporizador en píxeles. El icono de hechizo se dimensiona para coincidir."
L["Vertical gap in pixels between stacked bars."] = "Espacio vertical en píxeles entre las barras apiladas."
L["Font size for the bar's name and timer text."] = "Tamaño de fuente del nombre de la barra y del texto de temporizador."
L["Text outline style for bar text."] = "Estilo de contorno de texto para el texto de la barra."
L["Fallback fill color for bars whose spell has no icon-sampled color (most do). Each aura's color is normally taken from its icon; you can override per aura in the aura list tabs."] = "Color de relleno de reserva para las barras cuyo hechizo no tiene un color muestreado del icono (la mayoría lo tiene). El color de cada aura se toma normalmente de su icono; puedes anularlo por aura en las pestañas de la lista de auras."
L["Show Icon"] = "Mostrar icono"
L["Show the spell icon at the left edge of each bar."] = "Muestra el icono de hechizo en el borde izquierdo de cada barra."
L["Show Name"] = "Mostrar nombre"
L["Show the aura name on each bar."] = "Muestra el nombre del aura en cada barra."
L["Show Timer"] = "Mostrar temporizador"
L["Show the remaining-time text on each bar."] = "Muestra el texto de tiempo restante en cada barra."
L["Show a spark at the fill edge of each bar."] = "Muestra un destello en el borde de relleno de cada barra."
L["Default Sound"] = "Sonido por defecto"
L["Sound to play when any aura activates. Individual auras can override this in the aura list tabs."] = "Sonido que reproducir cuando se activa cualquier aura. Las auras individuales pueden anular esto en las pestañas de la lista de auras."
L["Play on Refresh"] = "Reproducir al renovar"
L["Also play the sound when an aura refreshes (is reapplied while already active). Useful for procs like Mace Stun where each trigger matters. Individual auras can override this in the aura list tabs."] = "Reproduce también el sonido cuando un aura se renueva (se reaplica estando ya activa). Útil para procs como Aturdimiento de maza, donde cada activación importa. Las auras individuales pueden anular esto en las pestañas de la lista de auras."
L["Swing Bar"] = "Barra de golpe"
L["Your character automatically fires auto-shots on a timer. If you cast an ability too late in the timer, it 'clips' (delays) your next auto-shot, costing you DPS. The bar turns green when it's safe to cast and red when casting would clip. Once you learn Steady Shot, a yellow zone appears for the window where Steady Shot would clip but instants and movement are still safe."] = "Tu personaje dispara automáticamente disparos automáticos según un temporizador. Si lanzas una habilidad demasiado tarde en el temporizador, 'recorta' (retrasa) tu siguiente disparo automático, costándote DPS. La barra se pone verde cuando es seguro lanzar y roja cuando lanzar recortaría. Una vez aprendes Steady Shot, aparece una zona amarilla para la ventana en la que Steady Shot recortaría pero los instantáneos y el movimiento siguen siendo seguros."
L["Seal twisting lets you get two seal procs on a single melee swing by swapping seals right before the hit lands. The bar turns green during the twist window — the last ~0.4 seconds before impact — telling you when to swap to your second seal."] = "El cambio de sellos te permite obtener dos procs de sello en un solo golpe cuerpo a cuerpo cambiando de sello justo antes de que impacte el golpe. La barra se pone verde durante la ventana de cambio — los últimos ~0.4 segundos antes del impacto — indicándote cuándo cambiar a tu segundo sello."
L["Tracks your melee swing timer — a bar that fills up as your next auto-attack approaches. Auto-hides between pulls."] = "Rastrea el temporizador de tu golpe cuerpo a cuerpo — una barra que se llena a medida que se acerca tu siguiente ataque automático. Se oculta automáticamente entre pulls."
L["Two bars track your main-hand and off-hand swing timers. When both weapons swing at the same time (synced), your Flurry haste charges aren't wasted on isolated off-hand hits, and Windfury extra attacks land alongside your normal swings. Bars turn green when synced and red when desynced — meaning one weapon has drifted ahead of the other."] = "Dos barras rastrean los temporizadores de golpe de tu mano principal y tu mano secundaria. Cuando ambas armas golpean a la vez (sincronizadas), tus cargas de celeridad de Flurry no se desperdician en golpes aislados de la mano secundaria, y los ataques adicionales de Windfury impactan junto con tus golpes normales. Las barras se ponen verdes cuando están sincronizadas y rojas cuando están desincronizadas — lo que significa que un arma se ha adelantado a la otra."
L["Tracks your melee swing timer. Slam resets this timer, so for maximum DPS you want to Slam right after a swing lands (when the bar reaches the end and resets). This avoids losing auto-attack time to the Slam cast.\n\n"] = "Rastrea el temporizador de tu golpe cuerpo a cuerpo. Slam reinicia este temporizador, así que para un DPS máximo conviene usar Slam justo después de que impacte un golpe (cuando la barra llega al final y se reinicia). Esto evita perder tiempo de ataque automático por el lanzamiento de Slam.\n\n"
L["Tracks your melee swing timer — a bar that fills up as your next auto-attack approaches. Auto-hides between pulls.\n\n"] = "Rastrea el temporizador de tu golpe cuerpo a cuerpo — una barra que se llena a medida que se acerca tu siguiente ataque automático. Se oculta automáticamente entre pulls.\n\n"
L["Tracks your auto-attack timer for wanding or melee. Only appears while actively attacking and auto-hides when you stop."] = "Rastrea el temporizador de tu ataque automático para varita o cuerpo a cuerpo. Solo aparece mientras atacas activamente y se oculta automáticamente cuando paras."
L["Tracks your melee swing timer. Shows separate main-hand and off-hand bars when dual-wielding."] = "Rastrea el temporizador de tu golpe cuerpo a cuerpo. Muestra barras separadas de mano principal y mano secundaria al usar dos armas."
L["Tracks your melee swing timer in Cat or Bear Form. Bear Form's 2.5s swing is useful for timing Maul. Auto-hides when not actively swinging."] = "Rastrea el temporizador de tu golpe cuerpo a cuerpo en Forma de gato u oso. El golpe de 2.5s de la Forma de oso es útil para sincronizar Mazazo. Se oculta automáticamente cuando no estás golpeando activamente."
L["Shows a weapon swing timer bar that fills as your next auto-attack approaches. Includes class-specific colored zones: Hunter shot clipping, Ret Paladin seal twisting, Enhancement/Warrior dual-wield sync. Auto-hides when not actively swinging."] = "Muestra una barra de temporizador de golpe de arma que se llena a medida que se acerca tu siguiente ataque automático. Incluye zonas de color específicas de cada clase: recorte de disparo de Cazador, cambio de sellos de Paladín Reprensión, sincronización de dos armas de Mejora/Guerrero. Se oculta automáticamente cuando no estás golpeando activamente."
L["Width of the swing bar in pixels."] = "Anchura de la barra de golpe en píxeles."
L["Height of the swing bar in pixels (single weapon). Per-class/spec: each class or spec remembers its own height."] = "Altura de la barra de golpe en píxeles (un arma). Por clase/especialización: cada clase o especialización recuerda su propia altura."
L["Wand Height"] = "Altura de varita"
L["Height of the swing bar in pixels for wand users (Mage, Priest, Warlock)."] = "Altura de la barra de golpe en píxeles para usuarios de varita (Mago, Sacerdote, Brujo)."
L["Dual-Wield Height"] = "Altura de dos armas"
L["Height of each bar when dual-wielding (MH and OH bars shown separately)."] = "Altura de cada barra al usar dos armas (las barras de mano principal y secundaria se muestran por separado)."
L["Dual-Wield Spacing"] = "Espaciado de dos armas"
L["Gap in pixels between the main-hand and off-hand bars."] = "Espacio en píxeles entre las barras de mano principal y mano secundaria."
L["Show a glowing spark at the fill edge of the bar."] = "Muestra un destello luminoso en el borde de relleno de la barra."
L["Hide Delay"] = "Retardo de ocultación"
L["Seconds to wait after the last swing before auto-hiding the bar."] = "Segundos que esperar tras el último golpe antes de ocultar automáticamente la barra."
L["The fill color of the swing bar. Disabled when class-specific coloring overrides the entire bar."] = "El color de relleno de la barra de golpe. Desactivado cuando el coloreado específico de clase anula toda la barra."
L["Timer Text"] = "Texto de temporizador"
L["Show Timer Text"] = "Mostrar texto de temporizador"
L["Show a countdown timer on the bar."] = "Muestra una cuenta atrás en la barra."
L["Font size for the timer text."] = "Tamaño de fuente del texto de temporizador."
L["Text outline style for the swing bar."] = "Estilo de contorno de texto para la barra de golpe."
L["Class Options"] = "Opciones de clase"
L["Enable Shot Zones"] = "Activar zonas de disparo"
L["Color the bar by auto-shot timing:\n\n|cffffffffGreen|r — Safe to cast anything and move freely.\n|cffffffffYellow|r — Steady Shot would clip, but instants and movement are safe.\n|cffffffffRed|r — Don't move or cast Multi-Shot (auto-shot animation playing)."] = "Colorea la barra según el momento del disparo automático:\n\n|cffffffffVerde|r — Seguro para lanzar cualquier cosa y moverse libremente.\n|cffffffffAmarillo|r — Steady Shot recortaría, pero los instantáneos y el movimiento son seguros.\n|cffffffffRojo|r — No te muevas ni lances Multi-Shot (la animación de disparo automático está en curso)."
L["Safe Zone (Green)"] = "Zona segura (verde)"
L["Bar color when it's safe to cast and move."] = "Color de la barra cuando es seguro lanzar y moverse."
L["Steady Zone (Yellow)"] = "Zona de Steady Shot (amarillo)"
L["Bar color when Steady Shot would clip, but instant shots and movement are still safe."] = "Color de la barra cuando Steady Shot recortaría, pero los disparos instantáneos y el movimiento siguen siendo seguros."
L["Stop Zone (Red)"] = "Zona de parada (rojo)"
L["Bar color when moving would cancel your auto-shot and Multi-Shot would clip."] = "Color de la barra cuando moverse cancelaría tu disparo automático y Multi-Shot recortaría."
L["Enable Twist Window"] = "Activar ventana de cambio"
L["Highlight the last ~0.4 seconds before your melee swing with a different color — your cue to swap seals for seal twisting."] = "Resalta los últimos ~0.4 segundos antes de tu golpe cuerpo a cuerpo con un color distinto — tu señal para cambiar de sello en el cambio de sellos."
L["Twist Window Color"] = "Color de ventana de cambio"
L["Bar color during the seal twist window."] = "Color de la barra durante la ventana de cambio de sellos."
L["Zone Opacity"] = "Opacidad de zona"
L["Opacity of the background zone indicators that preview upcoming color changes on the bar."] = "Opacidad de los indicadores de zona de fondo que previsualizan los próximos cambios de color en la barra."
L["Melee Weaving"] = "Intercalado cuerpo a cuerpo"
L["Show both ranged and melee swing bars simultaneously. For advanced hunters who weave melee attacks (e.g., Raptor Strike) between auto-shots."] = "Muestra a la vez las barras de golpe a distancia y cuerpo a cuerpo. Para cazadores avanzados que intercalan ataques cuerpo a cuerpo (p. ej., Golpe de raptor) entre disparos automáticos."
L["Enable Sync Colors"] = "Activar colores de sincronización"
L["Sync Threshold"] = "Umbral de sincronización"
L["Spell Config"] = "Config. de hechizos"
L["Spells"] = "Hechizos"
L["Click the button below to open the spell configuration window — enable/disable spells, reorder them, and drag between rows."] = "Haz clic en el botón de abajo para abrir la ventana de configuración de hechizos — activa/desactiva hechizos, reordénalos y arrástralos entre filas."
L["Open Spell Configuration"] = "Abrir configuración de hechizos"
L["Opens the spell configuration window where you can enable/disable spells, reorder them, and move them between rows using drag-and-drop."] = "Abre la ventana de configuración de hechizos donde puedes activar/desactivar hechizos, reordenarlos y moverlos entre filas mediante arrastrar y soltar."
L["Consumables"] = "Consumibles"
L["Track combat consumables on your HUD — potions, runes, and other items you use mid-fight. Each icon shows the item cooldown, buff duration, and bag count. For long-duration pre-pull buffs (elixirs, flasks, food), use a consumable-tracking addon like NovaConsumesHelper."] = "Rastrea consumibles de combate en tu interfaz — pociones, runas y otros objetos que usas en mitad del combate. Cada icono muestra el tiempo de reutilización del objeto, la duración del beneficio y la cantidad en la mochila. Para beneficios de larga duración previos al pull (elixires, frascos, comida), usa un complemento de rastreo de consumibles como NovaConsumesHelper."
L["Spec not yet detected"] = "Especialización aún no detectada"
L["Add Consumables"] = "Añadir consumibles"
L["Add by Item ID"] = "Añadir por ID de objeto"
L["Enter an item ID to track any consumable not listed above. You can find item IDs on Wowhead (the number in the URL) or with the idTip addon."] = "Introduce un ID de objeto para rastrear cualquier consumible no listado arriba. Puedes encontrar los ID de objeto en Wowhead (el número de la URL) o con el complemento idTip."
L["Invalid input — enter a numeric item ID."] = "Entrada no válida — introduce un ID de objeto numérico."
L["Added:"] = "Añadido:"
L["Tracked Consumables"] = "Consumibles rastreados"
L["Sounds"] = "Sonidos"
L["Play a sound when an ability becomes ready — when it comes off cooldown, becomes usable, or meets resource requirements. Set a default sound for all abilities, or override individual spells below.\n\nSound plays for all rows regardless of the Ready Glow row filter. Other settings still apply: combat-only, pre-trigger time, and once vs. re-trigger mode."] = "Reproduce un sonido cuando una habilidad pasa a estar lista — cuando sale del tiempo de reutilización, se vuelve utilizable o cumple los requisitos de recurso. Define un sonido por defecto para todas las habilidades o anula hechizos individuales abajo.\n\nEl sonido suena para todas las filas sin importar el filtro de filas del Resplandor de listo. El resto de ajustes siguen aplicándose: solo en combate, tiempo de preactivación y modo una vez vs. reactivar."
L["Support"] = "Apoyo"
L["Veev Addons Discord"] = "Discord de Veev Addons"
L["Discord URL"] = "URL de Discord"
L["Press Ctrl+C to copy the URL."] = "Pulsa Ctrl+C para copiar la URL."
L["VeevHUD is built with a $200/mo Claude subscription, late-night coding sessions, and unhealthy amounts of caffeine. I code for the love of the game, not for profit. Donations to help offset the costs are appreciated but never expected!"] = "VeevHUD se desarrolla con una suscripción a Claude de 200 $/mes, sesiones de programación nocturnas y cantidades poco saludables de cafeína. Programo por amor al juego, no por dinero. Las donaciones para ayudar a compensar los costes se agradecen, ¡pero nunca se esperan!"
L["Donate URL"] = "URL de donación"
L["Cooldown Pulse"] = "Pulso de reutilización"
L["Flashes a large icon in the center of the screen when a tracked ability comes off cooldown. A prominent visual cue that complements the ready glow on ability icons."] = "Hace destellar un icono grande en el centro de la pantalla cuando una habilidad rastreada sale del tiempo de reutilización. Una señal visual prominente que complementa el resplandor de listo en los iconos de habilidad."
L["Enable Cooldown Pulse"] = "Activar pulso de reutilización"
L["Master toggle for the cooldown pulse effect. When enabled, a large icon briefly flashes on screen each time a tracked ability finishes its cooldown."] = "Interruptor principal para el efecto de pulso de reutilización. Cuando está activado, un icono grande destella brevemente en pantalla cada vez que una habilidad rastreada termina su tiempo de reutilización."
L["How large the flashing icon appears on screen, in pixels."] = "El tamaño con el que el icono parpadeante aparece en pantalla, en píxeles."
L["Peak opacity of the icon during the flash. Lower values create a more subtle, ghostly effect."] = "Opacidad máxima del icono durante el destello. Los valores más bajos crean un efecto más sutil y fantasmal."
L["X Offset"] = "Desplazamiento X"
L["Horizontal offset from the center of your screen. Negative values move left, positive values move right."] = "Desplazamiento horizontal desde el centro de tu pantalla. Los valores negativos lo mueven a la izquierda, los positivos a la derecha."
L["Y Offset"] = "Desplazamiento Y"
L["Vertical offset from the center of your screen. Negative values move down, positive values move up."] = "Desplazamiento vertical desde el centro de tu pantalla. Los valores negativos lo mueven hacia abajo, los positivos hacia arriba."
L["Filtering"] = "Filtrado"
L["Which ability rows trigger the cooldown pulse. Primary Row is your core rotation — the most impactful notifications. Add Secondary to include throughput cooldowns too."] = "Qué filas de habilidades activan el pulso de reutilización. La fila primaria es tu rotación básica — las notificaciones de mayor impacto. Añade la secundaria para incluir también los tiempos de reutilización de rendimiento."
L["Only In Combat"] = "Solo en combate"
L["Only show cooldown pulses while you are in combat."] = "Muestra los pulsos de reutilización solo mientras estás en combate."
L["Ignore Cooldowns Below"] = "Ignorar reutilizaciones por debajo de"
L["Skip pulses for abilities with cooldowns shorter than this. Useful for filtering out short-cooldown rotational spells. Set to 0 to include everything."] = "Omite los pulsos de habilidades con tiempos de reutilización más cortos que este. Útil para filtrar hechizos de rotación con reutilización corta. Pon 0 para incluir todo."
L["Fade In Effect"] = "Efecto de aparición"
L["Size effect while the icon fades in. Grow: starts small, grows to normal. Shrink: starts big, shrinks to normal. None: no size change."] = "Efecto de tamaño mientras el icono aparece. Crecer: empieza pequeño y crece hasta lo normal. Encoger: empieza grande y encoge hasta lo normal. Ninguno: sin cambio de tamaño."
L["Grow"] = "Crecer"
L["Shrink"] = "Encoger"
L["Fade Out Effect"] = "Efecto de desaparición"
L["Size effect while the icon fades out. Grow: grows from normal to big. Shrink: shrinks from normal to small. None: no size change."] = "Efecto de tamaño mientras el icono desaparece. Crecer: crece de lo normal a grande. Encoger: encoge de lo normal a pequeño. Ninguno: sin cambio de tamaño."
L["Fade In"] = "Aparición"
L["How long the icon takes to fade in, in seconds."] = "Cuánto tarda el icono en aparecer, en segundos."
L["Hold Time"] = "Tiempo de permanencia"
L["How long the icon stays at peak opacity before fading out. Set to 0 for a quick flash, or increase for a longer notification."] = "Cuánto permanece el icono a opacidad máxima antes de desaparecer. Pon 0 para un destello rápido o auméntalo para una notificación más larga."
L["Fade Out"] = "Desaparición"
L["How long the icon takes to fade out, in seconds."] = "Cuánto tarda el icono en desaparecer, en segundos."
L["Early Trigger"] = "Activación temprana"
L["Fire the pulse this many seconds before the cooldown finishes. Gives you a head start on reacting. Set to 0 to pulse at the exact moment the ability becomes ready."] = "Lanza el pulso estos segundos antes de que termine el tiempo de reutilización. Te da ventaja para reaccionar. Pon 0 para pulsar en el momento exacto en que la habilidad pasa a estar lista."
L["Test Pulse"] = "Pulso de prueba"
L["Plays a test pulse so you can preview your current settings."] = "Reproduce un pulso de prueba para que puedas previsualizar tus ajustes actuales."
L["No consumables added yet. Select one from the dropdowns above."] = "Aún no se han añadido consumibles. Selecciona uno de los menús de arriba."
L["Remove"] = "Quitar"
L["Remove this consumable from tracking."] = "Quita este consumible del rastreo."
L["Any"] = "Cualquiera"
L["Own"] = "Propios"
L["Others"] = "Otros"
L["Icon"] = "Icono"
L["Show this aura as a compact icon in the icon row, or as a status bar with name and timer in the bar stack below the icons."] = "Muestra esta aura como un icono compacto en la fila de iconos, o como una barra de estado con nombre y temporizador en la pila de barras bajo los iconos."
L["Fill color for this aura's timer bar (Bar display mode only). Defaults to a vibrant color sampled from the spell's icon — change it here to override."] = "Color de relleno para la barra de temporizador de esta aura (solo en modo de visualización Barra). Por defecto es un color vibrante muestreado del icono del hechizo — cámbialo aquí para anularlo."
L["Toggle which class procs are tracked. Enabled procs appear as icons in the Aura Tracker when active."] = "Activa qué procs de clase se rastrean. Los procs activados aparecen como iconos en el Rastreador de auras cuando están activos."
L["Show this aura in the tracker."] = "Muestra esta aura en el rastreador."
L["Show the glowing border and backdrop halo when this aura is active. Disable for auras you want to track quietly without the glow drawing your eye."] = "Muestra el borde luminoso y el halo de fondo cuando esta aura está activa. Desactívalo para auras que quieras rastrear de forma discreta sin que el resplandor atraiga tu vista."
L["Sound to play when this aura activates. 'None' uses the global default from the Sound section above."] = "Sonido que reproducir cuando esta aura se activa. 'Ninguno' usa el valor global por defecto de la sección Sonido de arriba."
L["Refresh"] = "Renovar"
L["Also play the sound when this aura refreshes (is reapplied while already active)."] = "Reproduce también el sonido cuando esta aura se renueva (se reaplica estando ya activa)."
L["Settings"] = "Ajustes"
L["Class Procs"] = "Procs de clase"
L["External Buffs"] = "Beneficios externos"
L["Custom Auras"] = "Auras personalizadas"
L["Toggle which external buffs are tracked (from other players, consumables, or PvP powerups). These appear as icons in the Aura Tracker when active on you."] = "Activa qué beneficios externos se rastrean (de otros jugadores, consumibles o mejoras temporales JcJ). Estos aparecen como iconos en el Rastreador de auras cuando están activos en ti."
L["Track %s (ID: %s)"] = "Rastrear %s (ID: %s)"
L["Show the glowing border and backdrop halo when this aura is active."] = "Muestra el borde luminoso y el halo de fondo cuando esta aura está activa."
L["Sound to play when this aura activates. 'None' uses the global default."] = "Sonido que reproducir cuando esta aura se activa. 'Ninguno' usa el valor global por defecto."
L["Also play the sound when this aura refreshes."] = "Reproduce también el sonido cuando esta aura se renueva."
L["Add custom auras to track by spell ID or spell name. These work like procs — the icon appears when the buff is active on you."] = "Añade auras personalizadas que rastrear por ID de hechizo o nombre de hechizo. Funcionan como procs — el icono aparece cuando el beneficio está activo en ti."
L["Spell ID or Name"] = "ID o nombre de hechizo"
L["Enter a numeric spell ID or exact spell name and press Enter to add.\n\nYou can find spell IDs on Wowhead (the number at the end of the spell URL), or install the idTip addon to see spell IDs directly in tooltips."] = "Introduce un ID de hechizo numérico o el nombre exacto del hechizo y pulsa Intro para añadirlo.\n\nPuedes encontrar los ID de hechizo en Wowhead (el número al final de la URL del hechizo), o instalar el complemento idTip para ver los ID de hechizo directamente en las descripciones."
L["(icon shows when buff is active)"] = "(el icono aparece cuando el beneficio está activo)"
L["(by name — icon shows when buff is active)"] = "(por nombre — el icono aparece cuando el beneficio está activo)"
L["Current Custom Auras"] = "Auras personalizadas actuales"
L["Recently Seen Buffs"] = "Beneficios vistos recientemente"
L["No custom auras added yet."] = "Aún no se han añadido auras personalizadas."
L["(ID: "] = "(ID: "
L["Del"] = "Borrar"
L["Remove this custom aura."] = "Quita esta aura personalizada."
L["No recent buffs recorded yet. Play for a bit and reopen this tab."] = "Aún no se han registrado beneficios recientes. Juega un rato y vuelve a abrir esta pestaña."
L["All recent buffs are already tracked."] = "Todos los beneficios recientes ya se están rastreando."
L["Add"] = "Añadir"
L["In Combat"] = "En combate"
L["Out of Combat"] = "Fuera de combate"
L["Player"] = "Jugador"
L["Party"] = "Grupo"
L["Raid"] = "Banda"
L["Enable or disable this buff reminder."] = "Activa o desactiva este recordatorio de beneficio."
L["Time Threshold"] = "Umbral de tiempo"
L["Show the reminder when the buff has less than this many seconds remaining. Set to 0 to only remind when the buff is completely missing."] = "Muestra el recordatorio cuando al beneficio le quedan menos de estos segundos. Pon 0 para recordar solo cuando el beneficio falta por completo."
L["Combat"] = "Combate"
L["When to show this reminder based on combat state."] = "Cuándo mostrar este recordatorio según el estado de combate."
L["Track"] = "Rastrear"
L["Who to check for this buff.\n\n|cffffffffPlayer|r: Only check yourself.\n|cffffffffParty|r: Check all party members (or only yourself if solo).\n|cffffffffRaid|r: Check all raid members (downsizes to party if not in a raid)."] = "A quién comprobar este beneficio.\n\n|cffffffffJugador|r: solo a ti.\n|cffffffffGrupo|r: a todos los miembros del grupo (o solo a ti si estás en solitario).\n|cffffffffBanda|r: a todos los miembros de la banda (se reduce a grupo si no estás en una banda)."
L["Sound to play when this buff reminder appears. 'None' uses the global default from the General tab."] = "Sonido que reproducir cuando aparece este recordatorio de beneficio. 'Ninguno' usa el valor global por defecto de la pestaña General."
L["Min Stacks"] = "Acumulaciones mín."
L["Show the reminder when stacks fall below this number. Set to 0 to disable stack checking. This is an OR condition with the time threshold."] = "Muestra el recordatorio cuando las acumulaciones caen por debajo de este número. Pon 0 para desactivar la comprobación de acumulaciones. Es una condición O con el umbral de tiempo."
L["Priority"] = "Prioridad"
L["Which spell to remind first when no buff from this group is active."] = "Qué hechizo recordar primero cuando no hay ningún beneficio de este grupo activo."
L["Main Hand"] = "Mano principal"
L["Show a reminder when your main hand weapon is missing an enchant. Disable this if you prefer to benefit from a Shaman's Windfury Totem instead."] = "Muestra un recordatorio cuando a tu arma de mano principal le falta un encantamiento. Desactívalo si prefieres beneficiarte del Tótem furia de viento de un Chamán."
L["Off Hand"] = "Mano secundaria"
L["Show a reminder when your off hand weapon is missing an enchant."] = "Muestra un recordatorio cuando a tu arma de mano secundaria le falta un encantamiento."
L["Configure which buff reminders are active. Settings on this tab are per-spec — switching specs loads that spec's configuration."] = "Configura qué recordatorios de beneficio están activos. Los ajustes de esta pestaña son por especialización — cambiar de especialización carga la configuración de esa especialización."
L["Show Only Known Spells"] = "Mostrar solo hechizos conocidos"
L["Only shows spells you currently know. Disable to see all class buff spells, including ones you haven't learned yet."] = "Muestra solo los hechizos que conoces actualmente. Desactívalo para ver todos los hechizos de beneficio de la clase, incluidos los que aún no has aprendido."
L["Buff Reminders"] = "Recordatorios de beneficios"
L["Buff Reminders show a large, semi-transparent icon when a long-duration buff you should maintain is missing or about to expire. They are separate from the main HUD icons and only appear when action is needed.\n\nReminders automatically check that you know the spell and have the resources to cast it. Use the Spells tab to configure individual reminders."] = "Los recordatorios de beneficios muestran un icono grande y semitransparente cuando un beneficio de larga duración que deberías mantener falta o está a punto de expirar. Son independientes de los iconos principales de la interfaz y solo aparecen cuando se requiere acción.\n\nLos recordatorios comprueban automáticamente que conoces el hechizo y tienes los recursos para lanzarlo. Usa la pestaña Hechizos para configurar recordatorios individuales."
L["Enable Buff Reminders"] = "Activar recordatorios de beneficios"
L["Master toggle for the Buff Reminders feature. When disabled, no buff reminder icons will be shown."] = "Interruptor principal para la función de recordatorios de beneficios. Cuando está desactivado, no se mostrará ningún icono de recordatorio de beneficio."
L["The size of buff reminder icons in pixels."] = "El tamaño de los iconos de recordatorio de beneficio en píxeles."
L["The horizontal gap between buff reminder icons."] = "El espacio horizontal entre los iconos de recordatorio de beneficio."
L["Icon Opacity"] = "Opacidad de icono"
L["The opacity of the buff reminder icons."] = "La opacidad de los iconos de recordatorio de beneficio."
L["Text outline style for buff reminder text."] = "Estilo de contorno de texto para el texto de recordatorio de beneficio."
L["Pulse Animation"] = "Animación de pulso"
L["Reminder icons gently pulse to draw attention."] = "Los iconos de recordatorio pulsan suavemente para llamar la atención."
L["Respect Resource Cost"] = "Respetar coste de recurso"
L["Only show buff reminders when you have enough resources (mana, rage, energy) to cast the spell. Uncheck to always show reminders for missing buffs regardless of your current resource level."] = "Muestra los recordatorios de beneficio solo cuando tienes suficientes recursos (maná, furia, energía) para lanzar el hechizo. Desmarca para mostrar siempre los recordatorios de beneficios que faltan sin importar tu nivel de recurso actual."
L["Show While Resting"] = "Mostrar al descansar"
L["Show buff reminders while in inns and cities."] = "Muestra los recordatorios de beneficio mientras estás en posadas y ciudades."
L["Show While Mounted"] = "Mostrar al montar"
L["Show buff reminders while mounted."] = "Muestra los recordatorios de beneficio mientras estás montado."
L["When buff reminders appear or disappear, the remaining icons smoothly slide to re-center instead of snapping instantly. Disable for instant repositioning."] = "Cuando los recordatorios de beneficio aparecen o desaparecen, los iconos restantes se deslizan con suavidad para recentrarse en lugar de hacerlo de golpe. Desactívalo para un reposicionamiento instantáneo."
L["Click to Cast (Out of Combat)"] = "Clic para lanzar (fuera de combate)"
L["Makes reminder icons clickable — left-click casts the missing buff. Blizzard restricts addon casting to secure buttons that cannot be moved, shown, or hidden during combat, so clicking only works out of combat — in combat, reminders are visual-only and clicks pass through as normal."] = "Hace que los iconos de recordatorio se puedan pulsar: el clic izquierdo lanza el beneficio que falta. Blizzard restringe el lanzamiento de hechizos por parte de los addons a botones seguros que no se pueden mover, mostrar ni ocultar durante el combate, así que el clic solo funciona fuera de combate: en combate, los recordatorios son solo visuales y los clics pasan a través con normalidad."
L["Sound to play when a buff reminder first appears. Individual spells can override this in the Spells tab."] = "Sonido que reproducir cuando aparece por primera vez un recordatorio de beneficio. Los hechizos individuales pueden anular esto en la pestaña Hechizos."
L["Position"] = "Posición"
L["Horizontal offset of buff reminder icons relative to the HUD. The range adjusts to your screen resolution."] = "Desplazamiento horizontal de los iconos de recordatorio de beneficio respecto a la interfaz. El rango se ajusta a la resolución de tu pantalla."
L["Vertical offset of buff reminder icons relative to the HUD. The range adjusts to your screen resolution."] = "Desplazamiento vertical de los iconos de recordatorio de beneficio respecto a la interfaz. El rango se ajusta a la resolución de tu pantalla."
L["Toggle a sample buff reminder icon so you can see your settings in action."] = "Activa un icono de recordatorio de beneficio de muestra para que puedas ver tus ajustes en acción."
L["Default"] = "Por defecto"
L["Sound to play when the ready glow activates on any ability. Per-spell overrides below take priority."] = "Sonido que reproducir cuando el resplandor de listo se activa en cualquier habilidad. Las anulaciones por hechizo de abajo tienen prioridad."
L["Primary"] = "Primaria"
L["Secondary"] = "Secundaria"
L["Utility"] = "Utilidad"
L["Auxiliary"] = "Auxiliar"
