-- Strings added in the 2026-08 localization coverage pass.
-- AI-generated (Claude); native-speaker review welcome.
L["HUD Stack"] = "Pila de la interfaz"
L["Only attached elements appear here. Reorder them from top to bottom and tune the space between each pair."] = "Aquí solo aparecen los elementos acoplados. Reordénalos de arriba abajo y ajusta el espacio entre cada par."
L["Move Rows"] = "Mover filas"
L["Detach any ability row from the HUD stack, then drag it anywhere on the screen. While this tab is open, detached rows show drag handles and other HUD elements close the vacated space automatically."] = "Desacopla cualquier fila de habilidades de la pila de la interfaz y arrástrala a cualquier punto de la pantalla. Mientras esta pestaña está abierta, las filas desacopladas muestran tiradores de arrastre y el resto de elementos de la interfaz cierran automáticamente el espacio liberado."
L["Gap below"] = "Espacio debajo"
L["Global Cooldown"] = "Tiempo de reutilización global"
L["GCD Spiral Opacity"] = "Opacidad de espiral del GCD"
L["How dark the Global Cooldown swipe appears on icons. Independent from Cooldown Spiral Opacity, so you can hide the cooldown spiral while keeping the GCD swipe visible (or vice versa)."] = "Cuán oscuro aparece el barrido del tiempo de reutilización global en los iconos. Es independiente de la Opacidad de espiral de reutilización, así que puedes ocultar la espiral de reutilización manteniendo visible el barrido del GCD (o viceversa)."
L["Move separately"] = "Mover por separado"
L["Moves this ability row separately from the shared HUD stack so it can be placed anywhere on the screen. Turning it off returns the row to its configured layout order."] = "Mueve esta fila de habilidades por separado de la pila compartida de la interfaz, de modo que pueda colocarse en cualquier punto de la pantalla. Al desactivarlo, la fila vuelve a su orden de disposición configurado."
L["Reset Position"] = "Restablecer posición"
L["Moves this independent row back to the position it would occupy in the shared HUD stack while keeping independent positioning enabled."] = "Devuelve esta fila independiente a la posición que ocuparía en la pila compartida de la interfaz, manteniendo activado el posicionamiento independiente."
L["Horizontal Position"] = "Posición horizontal"
L["Fine-tunes this row's horizontal position relative to the center of the screen."] = "Ajusta con precisión la posición horizontal de esta fila respecto al centro de la pantalla."
L["Vertical Position"] = "Posición vertical"
L["Fine-tunes this row's vertical position relative to the center of the screen."] = "Ajusta con precisión la posición vertical de esta fila respecto al centro de la pantalla."
L["Independent row positioning cannot be edited during combat."] = "El posicionamiento independiente de filas no se puede editar durante el combate."
L["Drag to move %s"] = "Arrastra para mover %s"
L["Secondary Row"] = "Fila secundaria"
L["Auxiliary Row"] = "Fila auxiliar"
L["Row %d"] = "Fila %d"
